    int a = check ctx->callActivity(fetchOrder, {id: 1}, retryPolicy = STANDARD_RETRY);

    // 2. approvalPolicy as a module-level record reference
    int b = check ctx->callActivity(fetchOrder, {id: 2}, approvalPolicy = FINANCE_GATE);

